package com.wizzadrds.theworldremembers; import com.wizzadrds.theworldremembers.chronicle.*; import net.fabricmc.api.ClientModInitializer; import net.fabricmc.fabric.api.client.event.lifecycle.v1.ClientTickEvents; import net.fabricmc.fabric.api.client.keybinding.v1.KeyBindingHelper; import net.fabricmc.fabric.api.client.networking.v1.ClientPlayNetworking; import net.minecraft.client.KeyMapping; import net.minecraft.client.Minecraft; import net.minecraft.client.gui.screens.Screen; import net.minecraft.client.gui.GuiGraphics; import net.minecraft.network.chat.Component; import org.lwjgl.glfw.GLFW; import java.util.*; public final class TheWorldRemembersClient implements ClientModInitializer{static final KeyMapping KEY=KeyBindingHelper.registerKeyBinding(new KeyMapping("key.the_world_remembers.chronicle",GLFW.GLFW_KEY_K,KeyMapping.Category.MISC)); private static List<String> lines=List.of(); public void onInitializeClient(){ClientPlayNetworking.registerGlobalReceiver(ChronicleResponsePacket.TYPE,(p,c)->lines=p.lines());ClientTickEvents.END_CLIENT_TICK.register(m->{if(KEY.consumeClick())ClientPlayNetworking.send(new ChronicleRequestPacket());});} public static void open(){Minecraft.getInstance().setScreen(new Screen(Component.literal("Chronicles")){protected void render(GuiGraphics g,int mx,int my,float d){renderBackground(g,mx,my,d);g.drawCenteredString(font,title,getGuiScaledWidth()/2,18,0xffffff);int y=38;for(String line:lines){if(y>getGuiScaledHeight()-14)break;g.drawString(font,Component.literal(line),20,y,0xffffff);y+=12;} } public boolean isPauseScreen(){return false;}});}}